contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We are the deployer of c so this contract is c.owner. Call withdraw with any value.
    // The function is payable in this test so we can send funds to c beforehand using c.receive via the public payable function sendMoney? No — we must use only c's public/external functions directly.
    // To fund c we call c.sendMoney targeting itself: c.sendMoney(address(c), amount, ""); That call is onlyOwner, and this contract is owner, so it will execute and forward value 0 (sendMoney doesn't accept value), but sendMoney does not send value. Instead, to fund c we rely on the test being payable and directly call c.withdraw(0) etc. However withdraw is onlyOwner and will transfer from c to owner; we need to ensure c has some balance to test non-increase. The simplest rule: withdrawing cannot increase depositsCount nor increase c.balance. This can be checked even if balance is zero.

    // The single public test function per constraints:
    function run(uint value) public payable {
        require(true);

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool reverted;
        // Call withdraw; this contract is owner of c because it deployed c per framework.
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: regardless of revert, depositsCount never increases, and c.balance never increases.
        assert(afterCount <= beforeCount && afterBalance <= beforeBalance);
    }

    receive() external payable {}
}

